$p=$product;$currency=storefront_currency();$config=require __DIR__.'/site-config.php';$path=storefront_product_url($p);$description=trim(strip_tags($p['description']??''))?:$p['title'].' оптом для клубов, магазинов и тренеров. Уточните цену и наличие у менеджера.';$metaDescription=preg_replace('/\s+/u',' ',implode('',array_slice(preg_split('//u',$description,-1,PREG_SPLIT_NO_EMPTY),0,180)));
