?><!doctype html><html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><?=sf_meta($p['title'].' оптом — Lucky',$metaDescription,$path,$photo,'product')?><link rel="icon" href="/clover.svg"><link rel="stylesheet" href="/styles.css?v=leads-seo-v1"><link rel="stylesheet" href="/leads.css?v=2"><script type="application/ld+json"><?=sf_json($schema)?></script></head><body>
<header class="site-header product-header"><a class="brand" href="/"><img class="brand-logo" src="/lucky-logo.svg" alt="Lucky"><span class="brand-mode">ОПТОМ</span></a><a class="product-back" href="/#catalog">← Весь каталог</a></header>
<main class="product-page"><nav class="product-breadcrumbs" aria-label="Хлебные крошки"><a href="/">Главная</a><span aria-hidden="true">/</span><a href="/#catalog">Каталог</a><span aria-hidden="true">/</span><span><?=sf_e($p['title'])?></span></nav><div class="product-page-layout"><div class="product-page-photos"><?php foreach(sf_photos($p) as $image):?><img src="<?=sf_e(storefront_image($image))?>" alt="<?=sf_e($p['title'])?>" loading="lazy"><?php endforeach;?></div><section class="product-page-info"><p class="section-kicker"><?=sf_e($p['brand']??'Lucky')?></p><h1><?=sf_e($p['title'])?></h1><p class="product-page-meta"><?=sf_e(sf_sport($p,$data['categories']))?> · Артикул: <?=sf_e($p['article']??$p['id'])?></p><div class="product-page-buy"><div><span class="product-page-label">Оптовая цена</span><p class="product-page-price" data-prices="<?=sf_e(json_encode($p['priceFrom']??[]))?>"><?=sf_e(sf_price($p,$currency))?></p></div><label class="product-currency">Валюта <select id="productCurrency" aria-label="Валюта цены"><?php foreach(['RUB'=>'Рубли ₽','KZT'=>'Тенге ₸','USD'=>'Доллары $'] as $c=>$name):?><option value="<?=$c?>"<?=$currency===$c?' selected':''?>><?=$name?></option><?php endforeach;?></select></label></div><p class="product-page-note">Точную цену для вашего объёма, наличие и сроки пришлёт менеджер. Минимальный заказ — от <?=(int)$config['minimumQuantity']?> шт.</p><div class="product-page-actions"><button class="dialog-primary product-page-cta" type="button" data-request-product="<?=sf_e($p['id'])?>" data-request-title="<?=sf_e($p['title'].(isset($p['article'])&&$p['article']!==''?' ('.$p['article'].')':''))?>">Запросить оптовую цену</button><a class="product-page-chat" href="<?=sf_e($config['whatsapp'])?>" target="_blank" rel="noopener">WhatsApp</a><a class="product-page-chat" href="<?=sf_e($config['telegram'])?>" target="_blank" rel="noopener">Telegram</a></div><?php $sizes=sf_sizes($p);?><h2>Размеры</h2><?php if($sizes):?><div class="product-chips"><?php foreach($sizes as $size):?><span><?=sf_e($size)?></span><?php endforeach;?></div><?php else:?><p>Размеры уточнит менеджер.</p><?php endif;?><?php if(!empty($p['colors'])):?><h2>Цвета</h2><div class="product-chips"><?php foreach($p['colors'] as $color):?><span><?=sf_e($color)?></span><?php endforeach;?></div><?php endif;?><h2>Описание</h2><p class="product-page-description"><?=nl2br(sf_e($description))?></p></section></div><?=sf_terms()?></main><?=sf_form()?>
